import { PlantPage } from "@plantopedia/contracts";

export async function readPlants(
  baseUrl: string, token: string, signal?: AbortSignal,
): Promise<PlantPage> {
  const response = await fetch(`${baseUrl.replace(/\/$/, "")}/v1/plants`, {
    headers: { Authorization: `Bearer ${token}` },
    ...(signal ? { signal } : {}),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const raw: unknown = await response.json();
  return PlantPage.parse(raw);
}

import { useQuery } from "@tanstack/react-query";
import { Button, Text, View } from "react-native";
import { useSessionApi } from "../../services/session";

export default function GardenStatus() {
  const { api, owner } = useSessionApi();
  const plants = useQuery({
    queryKey: [owner, "plants"],
    queryFn: () => api.plants(),
  });
  if (!plants.data) {
    if (plants.isPending) return <Text>Loading your garden…</Text>;
    return <View><Text>Your garden could not be loaded.</Text>
      <Button title="Try again" onPress={() => void plants.refetch()} />
    </View>;
  }
  return (
    <View style={{ padding: 24, gap: 12 }}>
      <Text>{plants.data.items.length === 0
        ? "Your garden is empty. Try saving your first plant."
        : `${plants.data.items.length} plants on this page`}</Text>
      {plants.data.items.map(plant =>
        <Text key={plant.id}>{plant.nickname}</Text>)}
      {plants.isFetching && <Text>Checking for updates…</Text>}
      {plants.isError && <Text>Showing saved query data; refresh failed.</Text>}
      <Button title="Refresh" disabled={plants.isFetching}
        onPress={() => void plants.refetch()} />
    </View>
  );
}

import { useQueryClient } from "@tanstack/react-query";

export function useRefreshPlant(owner: string, plantId: string) {
  const query = useQueryClient();
  return () => query.invalidateQueries({
    queryKey: [owner, "plant", plantId],
  });
}
